-- DDL: create user_behavior_events if it does not exist yet
CREATE TABLE IF NOT EXISTS user_behavior_events (
    id              BIGSERIAL    PRIMARY KEY,
    user_id         VARCHAR(36)  NOT NULL,
    product_id      BIGINT       NOT NULL,
    event_type      VARCHAR(20)  NOT NULL,
    session_id      VARCHAR(36),
    quantity        INTEGER      DEFAULT 1,
    price_at_event  NUMERIC(15,2),
    source          VARCHAR(30),
    device_type     VARCHAR(15),
    created_at      TIMESTAMP    NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_ube_user_id    ON user_behavior_events(user_id);
CREATE INDEX IF NOT EXISTS idx_ube_product_id ON user_behavior_events(product_id);
CREATE INDEX IF NOT EXISTS idx_ube_created_at ON user_behavior_events(created_at);

